import agent


def Run(ctx, a):
    j_read = agent.jobs.start(fs.read, "README.md")
    j_glob = agent.jobs.start(fs.glob, "*")

    read_res = j_read.result()
    glob_res = j_glob.result()

    text = getattr(read_res, "text", read_res)
    lines = text.splitlines() if isinstance(text, str) else []

    files = []
    for entry in glob_res:
        if isinstance(entry, str):
            files.append(entry)
        else:
            files.append(getattr(entry, "path", getattr(entry, "name", str(entry))))

    return {"read_lines": len(lines), "files": files}

