from html.parser import HTMLParser

VOID = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}

class Check(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.errors = []
        self.ids = []
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if "id" in d:
            self.ids.append(d["id"])
        if tag not in VOID:
            self.stack.append(tag)
    def handle_startendtag(self, tag, attrs):
        d = dict(attrs)
        if "id" in d:
            self.ids.append(d["id"])
    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if not self.stack:
            self.errors.append("unexpected </%s>" % tag)
        elif self.stack[-1] != tag:
            self.errors.append("mismatch: </%s> closes <%s>" % (tag, self.stack[-1]))
            if tag in self.stack:
                while self.stack and self.stack.pop() != tag:
                    pass
        else:
            self.stack.pop()

def Run(ctx, a):
    page = fs.read("index.html")
    text = page.text
    p = Check()
    p.feed(text)
    p.close()

    required = {
        "add form": 'id="new-form"',
        "task input": 'id="new-task"',
        "list": 'id="list"',
        "localStorage read": 'localStorage.getItem(KEY)',
        "localStorage write": 'localStorage.setItem(KEY, JSON.stringify(items))',
        "toggle handler": 'box.addEventListener("change"',
        "delete handler": 'del.addEventListener("click"',
        "add handler": 'form.addEventListener("submit"',
        "escaping add (textContent)": 'label.textContent = item.text',
    }
    checks = {k: (v in text) for k, v in required.items()}
    checks["no external scripts"] = "<script src" not in text.lower()
    checks["no external styles"] = "stylesheet" not in text.lower()
    checks["balanced tags"] = not p.errors and not p.stack
    checks["no inline event handlers"] = "onclick=" not in text.lower()

    return {
        "bytes": len(text.encode()),
        "lines": text.count("\n") + 1,
        "ids": p.ids,
        "unclosed": p.stack,
        "html_errors": p.errors,
        "checks": checks,
        "all_passed": all(checks.values()),
        "head": text[:180],
        "tail": text[-120:],
    }

