import re

def strip_js(src):
    out = []
    i, n = 0, len(src)
    state = None  # None, "'", '"', "`", "//", "/*"
    while i < n:
        c = src[i]
        nxt = src[i+1] if i+1 < n else ""
        if state is None:
            if c in "'\"`":
                state = c; out.append(c); i += 1; continue
            if c == "/" and nxt == "/":
                state = "//"; i += 2; continue
            if c == "/" and nxt == "*":
                state = "/*"; i += 2; continue
            out.append(c); i += 1; continue
        if state == "//":
            if c == "\n":
                state = None; out.append(c)
            i += 1; continue
        if state == "/*":
            if c == "*" and nxt == "/":
                state = None; i += 2; continue
            i += 1; continue
        # in string
        out.append(c)
        if c == "\\":
            if i+1 < n: out.append(src[i+1])
            i += 2; continue
        if c == state:
            state = None
            out.append(c)
        i += 1
    return "".join(out), state

def Run(ctx, a):
    text = fs.read("index.html").text
    scripts = re.findall(r"<script>(.*?)</script>", text, re.S)
    out = {"script_blocks": len(scripts)}
    ok = True
    for idx, s in enumerate(scripts):
        stripped, end_state = strip_js(s)
        pairs = {")": "(", "]": "[", "}": "{"}
        stack, err = [], None
        for j, ch in enumerate(stripped):
            if ch in "([{":
                stack.append(ch)
            elif ch in ")]}":
                if not stack or stack[-1] != pairs[ch]:
                    err = "unbalanced %r at offset %d" % (ch, j)
                    break
                stack.pop()
        good = err is None and not stack and end_state is None
        ok = ok and good
        out["block_%d" % idx] = {"ok": good, "error": err, "unclosed": stack[-6:], "string_state": end_state}
    out["all_js_balanced"] = ok

    # sanity: every function referenced is defined, ids used in JS exist in DOM
    dom_ids = set(re.findall(r'id="([^"]+)"', text))
    used_ids = set(re.findall(r'getElementById\("([^"]+)"\)', text))
    out["missing_dom_ids"] = sorted(used_ids - dom_ids)
    out["unused_dom_ids"] = sorted(dom_ids - used_ids)
    out["len_ok"] = 0 < len(text) < 20000
    return out

