<script>
(function () {
  "use strict";

  var STORAGE_KEY = "todo.items.v1";
  var list = document.getElementById("list");
  var form = document.getElementById("todo-form");
  var input = document.getElementById("new-todo");
  var count = document.getElementById("count");
  var empty = document.getElementById("empty");
  var todos = load();

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (t) { return t && typeof t.text === "string"; })
        .map(function (t) {
          return {
            id: typeof t.id === "string" ? t.id : makeId(),
            text: t.text,
            done: t.done === true
          };
        });
    } catch (err) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (err) {
      /* Storage can be full or blocked; the app still works in memory. */
    }
  }

  function makeId() {
    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return window.crypto.randomUUID();
    }
    return Date.now().toString(36) + Math.random().toString(36).slice(2);
  }

  function render() {
    list.textContent = "";
    todos.forEach(function (todo) {
      var li = document.createElement("li");
      li.className = todo.done ? "done" : "";
      li.dataset.id = todo.id;

      var box = document.createElement("input");
      box.type = "checkbox";
      box.checked = todo.done;
      box.setAttribute("aria-label", "Mark done: " + todo.text);
      box.addEventListener("change", function () { toggle(todo.id); });

      var label = document.createElement("label");
      label.textContent = todo.text;
      label.title = todo.text;
      label.addEventListener("click", function () { toggle(todo.id); });

      var del = document.createElement("button");
      del.type = "button";
      del.className = "delete";
      del.textContent = "\u00d7";
      del.setAttribute("aria-label", "Delete: " + todo.text);
      del.title = "Delete";
      del.addEventListener("click", function () { remove(todo.id); });

      li.appendChild(box);
      li.appendChild(label);
      li.appendChild(del);
      list.appendChild(li);
    });

    var remaining = todos.filter(function (t) { return !t.done; }).length;
    count.textContent = todos.length
      ? remaining + " left \u00b7 " + todos.length + " total"
      : "";
    empty.hidden = todos.length > 0;
  }

  function add(text) {
    var value = text.trim();
    if (!value) return;
    todos.push({ id: makeId(), text: value, done: false });
    save();
    render();
  }

  function toggle(id) {
    var todo = todos.find(function (t) { return t.id === id; });
    if (!todo) return;
    todo.done = !todo.done;
    save();
    render();
  }

  function remove(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    add(input.value);
    input.value = "";
    input.focus();
  });

  /* Keep multiple open tabs in sync. */
  window.addEventListener("storage", function (event) {
    if (event.key === STORAGE_KEY) {
      todos = load();
      render();
    }
  });

  render();
})();
