from html.parser import HTMLParser

VOID = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}

class Checker(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.ids = []
        self.errors = []
        self.tags = []
        self.has_script = False
        self.has_style = False
    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        d = dict(attrs)
        if "id" in d:
            self.ids.append(d["id"])
        if tag == "script":
            self.has_script = True
        if tag == "style":
            self.has_style = True
        if tag not in VOID:
            self.stack.append(tag)
    def handle_startendtag(self, tag, attrs):
        self.tags.append(tag)
        d = dict(attrs)
        if "id" in d:
            self.ids.append(d["id"])
    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if not self.stack:
            self.errors.append("unexpected </%s>" % tag)
            return
        if self.stack[-1] != tag:
            self.errors.append("mismatch: open <%s>, close </%s>" % (self.stack[-1], tag))
            # pop to tag if present to continue
            if tag in self.stack:
                while self.stack and self.stack[-1] != tag:
                    self.stack.pop()
                if self.stack:
                    self.stack.pop()
        else:
            self.stack.pop()

def strip_js(src):
    out = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        nxt = src[i+1] if i+1 < n else ""
        if c == "/" and nxt == "/":
            i = src.find("\n", i)
            if i == -1:
                break
            continue
        if c == "/" and nxt == "*":
            end = src.find("*/", i+2)
            i = n if end == -1 else end + 2
            continue
        if c in "\"'`":
            quote = c
            i += 1
            while i < n:
                if src[i] == "\\":
                    i += 2
                    continue
                if src[i] == quote:
                    i += 1
                    break
                i += 1
            out.append(" ")
            continue
        out.append(c)
        i += 1
    return "".join(out)

def balanced(src):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    line = 1
    for ch in src:
        if ch == "\n":
            line += 1
        elif ch in "([{":
            stack.append((ch, line))
        elif ch in ")]}":
            if not stack or stack[-1][0] != pairs[ch]:
                return False, "unexpected %r at line %d" % (ch, line)
            stack.pop()
    if stack:
        return False, "unclosed %r from line %d" % stack[-1]
    return True, "ok"

