  var form = document.getElementById("add-form");
  var input = document.getElementById("new-todo");
  var list = document.getElementById("list");
  var empty = document.getElementById("empty");
  var count = document.getElementById("count");
  var summary = document.getElementById("summary");
  var error = document.getElementById("error");

  var todos = load();

  function uid() {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 9);
  }

  function load() {
    var raw;
    try {
      raw = localStorage.getItem(KEY);
    } catch (err) {
      console.warn("Storage is unavailable; tasks will not persist.", err);
      return [];
    }
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (t) {
          return t && typeof t.text === "string" && t.text.trim() !== "";
        })
        .map(function (t) {
          return {
            id: typeof t.id === "string" && t.id ? t.id : uid(),
            text: t.text.trim().slice(0, MAX_LEN),
            done: t.done === true
          };
        });
    } catch (err) {
      console.warn("Saved tasks were unreadable; starting fresh.", err);
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(KEY, JSON.stringify(todos));
    } catch (err) {
      console.warn("Could not save tasks.", err);
    }
  }

  function updateStats() {
    var total = todos.length;
    var left = todos.filter(function (t) { return !t.done; }).length;

    count.textContent = total + (total === 1 ? " task" : " tasks");
    summary.textContent =
      total === 0 ? "All clear" :
      left === 0 ? "Everything done" :
      left + (left === 1 ? " task to go" : " tasks to go");
    empty.hidden = total !== 0;
  }

  function render() {
    list.textContent = "";
    var frag = document.createDocumentFragment();

    todos.forEach(function (todo) {
      var li = document.createElement("li");
      li.className = "item" + (todo.done ? " done" : "");
      li.dataset.id = todo.id;

      var label = document.createElement("label");
      label.className = "row";

      var box = document.createElement("input");
      box.type = "checkbox";
      box.className = "check";
      box.checked = todo.done;
      box.setAttribute("aria-label", "Mark \u201C" + todo.text + "\u201D as " + (todo.done ? "not done" : "done"));

      var text = document.createElement("span");
      text.className = "text";
      text.textContent = todo.text;

      var del = document.createElement("button");
      del.type = "button";
      del.className = "delete";
      del.dataset.action = "delete";
      del.setAttribute("aria-label", "Delete \u201C" + todo.text + "\u201D");
      del.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg>';

      label.appendChild(box);
      label.appendChild(text);
      li.appendChild(label);
      li.appendChild(del);
      frag.appendChild(li);
    });

    list.appendChild(frag);
    updateStats();
  }

  function showError() {
    error.hidden = false;
  }
  function hideError() {
    error.hidden = true;
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    var text = input.value.trim();
    if (!text) {
      showError();
      input.focus();
      return;
    }
    todos.push({ id: uid(), text: text.slice(0, MAX_LEN), done: false });
    save();
    render();
    form.reset();
    hideError();
    input.focus();
  });

  input.addEventListener("input", hideError);

  function find(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return todos[i];
    }
    return null;
  }

  list.addEventListener("change", function (event) {
    var box = event.target;
    if (!box.classList || !box.classList.contains("check")) return;
    var li = box.closest(".item");
    var todo = li && find(li.dataset.id);
    if (!todo) return;

    todo.done = box.checked;
    li.classList.toggle("done", todo.done);
    box.setAttribute("aria-label", "Mark \u201C" + todo.text + "\u201D as " + (todo.done ? "not done" : "done"));
    save();
    updateStats();
  });

  list.addEventListener("click", function (event) {
    var btn = event.target.closest("[data-action='delete']");
    if (!btn) return;
    var li = btn.closest(".item");
    if (!li) return;

    todos = todos.filter(function (t) { return t.id !== li.dataset.id; });
    save();
    render();
    input.focus();
  });

  // Keep multiple open copies of the page in sync.
  window.addEventListener("storage", function (event) {
    if (event.key !== KEY) return;
    todos = load();
    render();
  });

  render();
})();
</script>
</body>
</html>
'''

