import asyncio
import concurrent.futures
import dataclasses
import inspect

import agent
from agent import agents, fs


def _ser(x, depth=0):
    """Best-effort JSON-serializable conversion of SDK return objects."""
    if depth > 6:
        return repr(x)
    if x is None or isinstance(x, (str, int, float, bool)):
        return x
    if isinstance(x, dict):
        return {str(k): _ser(v, depth + 1) for k, v in x.items()}
    if isinstance(x, (list, tuple, set)):
        return [_ser(v, depth + 1) for v in x]
    if dataclasses.is_dataclass(x) and not isinstance(x, type):
        try:
            return _ser(dataclasses.asdict(x), depth + 1)
        except Exception:
            pass
    d = getattr(x, "__dict__", None)
    if isinstance(d, dict) and d:
        return {k: _ser(v, depth + 1) for k, v in d.items() if not k.startswith("_")}
    slots = getattr(type(x), "__slots__", None)
    if slots:
        return {
            s: _ser(getattr(x, s), depth + 1)
            for s in (slots if isinstance(slots, (list, tuple)) else [slots])
            if hasattr(x, s)
        }
    return repr(x)


def _resolve(v):
    """Block on a job result whether it is a plain value or an awaitable."""
    if not inspect.isawaitable(v):
        return v

    async def _await(aw):
        return await aw

    try:
        asyncio.get_running_loop()
        running = True
    except RuntimeError:
        running = False

    if running:
        # Sync entry point invoked inside an active loop: resolve in a worker thread.
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
            return ex.submit(lambda: asyncio.run(_await(v))).result()
    return asyncio.run(_await(v))


def Run(ctx, a):
    # Detached subagent: launch and return its handle, do not wait for it.
    detached = agents.tasks.start(
        "build",
        "Read README.md and report its first line in your final answer.",
        "read-readme",
    )

    # Concurrent independent jobs.
    read_job = agent.jobs.start(fs.read, "README.md")
    glob_job = agent.jobs.start(fs.glob, "*")

    read_result = _resolve(read_job.result())
    glob_result = _resolve(glob_job.result())

    return {
        "detached": _ser(detached),
        "read": _ser(read_result),
        "glob": _ser(glob_result),
    }

